import{_ as o,o as t,c as a,a0 as d}from"./chunks/framework.DqMqoJl9.js";const h=JSON.parse('{"title":"UI 事件","description":"","frontmatter":{},"headers":[],"relativePath":"browser/3-ui-event.md","filePath":"browser/3-ui-event.md","lastUpdated":1791573371000}'),c={name:"browser/3-ui-event.md"};function l(r,e,n,s,i,p){return t(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="ui-事件" tabindex="-1">UI 事件 <a class="header-anchor" href="#ui-事件" aria-label="Permalink to &quot;UI 事件&quot;">​</a></h1><h2 id="_1-鼠标事件" tabindex="-1">1 鼠标事件 <a class="header-anchor" href="#_1-鼠标事件" aria-label="Permalink to &quot;1 鼠标事件&quot;">​</a></h2><h3 id="_1-1-鼠标事件类型" tabindex="-1">1.1 鼠标事件类型 <a class="header-anchor" href="#_1-1-鼠标事件类型" aria-label="Permalink to &quot;1.1 鼠标事件类型&quot;">​</a></h3><ul><li><code>mousedown/mouseup</code> 在元素上点击/释放鼠标按钮</li><li><code>mouseover/mouseout</code> 鼠标指针从一个元素上移入/移出</li><li><code>mousemove</code> 鼠标在元素上的每个移动都会触发此事件</li><li><code>click</code> 如果使用的是鼠标左键，则在同一个元素上的 mousedown 及 mouseup 相继触发后，触发该事件</li><li><code>dblclick</code> 在短时间内双击同一元素后触发。如今已经很少使用了</li><li><code>contextmenu</code> 在鼠标右键被按下时触发。还有其他打开上下文菜单的方式，例如使用特殊的键盘按键，在这种情况下它也会被触发，因此它并不完全是鼠标事件</li><li>...</li></ul><h3 id="_1-2-事件顺序" tabindex="-1">1.2 事件顺序 <a class="header-anchor" href="#_1-2-事件顺序" aria-label="Permalink to &quot;1.2 事件顺序&quot;">​</a></h3><p>一个用户操作可能会触发多个事件</p><p>例如，点击鼠标左键，在鼠标左键被按下时，会首先触发 <code>mousedown</code>，然后当鼠标左键被释放时，会触发 <code>mouseup</code> 和 <code>click</code></p><blockquote><p>在单个动作触发多个事件时，事件的顺序是固定的</p></blockquote><h3 id="_1-3-鼠标按钮" tabindex="-1">1.3 鼠标按钮 <a class="header-anchor" href="#_1-3-鼠标按钮" aria-label="Permalink to &quot;1.3 鼠标按钮&quot;">​</a></h3><p>与点击相关的事件始终具有 button 属性，该属性允许获取确切的鼠标按钮</p><p><strong><code>event.button</code> 的所有可能值如下：</strong></p><table tabindex="0"><thead><tr><th>鼠标按键状态</th><th>event.button</th></tr></thead><tbody><tr><td>左键 (主要按键)</td><td>0</td></tr><tr><td>中键 (辅助按键)</td><td>1</td></tr><tr><td>右键 (次要按键)</td><td>2</td></tr><tr><td>X1 键 (后退按键)</td><td>3</td></tr><tr><td>X2 键 (前进按键)</td><td>4</td></tr></tbody></table><p>触屏设备中的点按操作也会触发类似的事件</p><p><strong>过时的 <code>event.which</code></strong>，一些老代码可能会使用 <code>event.which</code> 属性来获得按下的按键</p><h3 id="_1-4-组合键" tabindex="-1">1.4 组合键 <a class="header-anchor" href="#_1-4-组合键" aria-label="Permalink to &quot;1.4 组合键&quot;">​</a></h3><p>所有的鼠标事件都包含有关按下的组合键的信息</p><p>组合键：<code>shift</code>，<code>alt</code>，<code>ctrl</code>，<code>meta</code></p><p><strong>事件属性：</strong></p><ul><li><strong>shiftKey：</strong> Shift</li><li><strong>altKey：</strong> Alt（或对于 Mac 是 Opt）</li><li><strong>ctrlKey：</strong> Ctrl</li><li><strong>metaKey：</strong> 对于 Mac 是 Cmd</li></ul><blockquote><p>注意：在 Mac 上我们通常使用 Cmd 代替 Ctrl</p></blockquote><p>如果在事件期间按下了相应的键，则它们为 true</p><p>下面这个按钮仅在 Alt+Shift+click 时才有效：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">button</span><span style="color:#6F42C1;"> id</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;button&quot;</span><span style="color:#24292E;">&gt;Alt+Shift+Click on me!&lt;/</span><span style="color:#22863A;">button</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  button.</span><span style="color:#6F42C1;">onclick</span><span style="color:#D73A49;"> =</span><span style="color:#D73A49;"> function</span><span style="color:#24292E;">(</span><span style="color:#E36209;">event</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#D73A49;">    if</span><span style="color:#24292E;"> (event.altKey </span><span style="color:#D73A49;">&amp;&amp;</span><span style="color:#24292E;"> event.shiftKey) {</span></span>
<span class="line"><span style="color:#6F42C1;">      alert</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;Hooray!&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">    }</span></span>
<span class="line"><span style="color:#24292E;">  };</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="_1-5-坐标" tabindex="-1">1.5 坐标 <a class="header-anchor" href="#_1-5-坐标" aria-label="Permalink to &quot;1.5 坐标&quot;">​</a></h3><p>所有的鼠标事件都提供了两种形式的坐标：</p><ul><li>相对于窗口的坐标：<code>clientX</code> 和 <code>clientY</code></li><li>相对于文档的坐标：<code>pageX</code> 和 <code>pageY</code></li></ul><p>相对于文档的坐标 <code>pageX/Y</code> 以文档的左上角为参照物，并且同一位置的坐标<strong>不随</strong>页面的滚动而改变。相对于窗口的坐标 <code>clientX/Y</code> 以当前窗口的左上角为参照物，并且同一位置的坐标<strong>会随</strong>着页面的滚动而改变</p><h2 id="_2-鼠标移动" tabindex="-1">2 鼠标移动 <a class="header-anchor" href="#_2-鼠标移动" aria-label="Permalink to &quot;2 鼠标移动&quot;">​</a></h2><h3 id="_2-1-mouseover-和-mouseout" tabindex="-1">2.1 mouseover 和 mouseout <a class="header-anchor" href="#_2-1-mouseover-和-mouseout" aria-label="Permalink to &quot;2.1 mouseover 和 mouseout&quot;">​</a></h3><p>当鼠标指针移到某个元素上时，<code>mouseover</code> 事件就会发生，而当鼠标离开该元素时，<code>mouseout</code> 事件就会发生</p><p>这些事件很特别，因为它们具有 <code>relatedTarget</code> 属性</p><p>此属性是对 <code>target</code> 的补充。当鼠标从一个元素离开并去往另一个元素时，其中一个元素就变成了 <code>target</code>，另一个就变成了 <code>relatedTarget</code></p><p><strong>对于 mouseover：</strong></p><ul><li><code>event.target</code> —— 是鼠标移过的那个元素</li><li><code>event.relatedTarget</code> —— 是鼠标来自的那个元素（relatedTarget → target）</li></ul><p><strong>对于 mouseout ：</strong></p><ul><li><code>event.target</code> —— 是鼠标离开的元素。</li><li><code>event.relatedTarget</code> —— 是鼠标移动到的，当前指针位置下的元素（target → relatedTarget）。</li></ul><blockquote><p><code>relatedTarget</code> 可以为 <code>null</code>，意味着鼠标不是来自另一个元素，而是来自窗口之外。或者它离开了窗口</p></blockquote><h3 id="_2-2-跳过元素" tabindex="-1">2.2 跳过元素 <a class="header-anchor" href="#_2-2-跳过元素" aria-label="Permalink to &quot;2.2 跳过元素&quot;">​</a></h3><p>浏览器会一直检查鼠标的位置。如果发现了变化，就会触发事件。这意味着，如果访问者非常快地移动鼠标，那么某些 DOM 元素就可能被跳过</p><blockquote><p>但是如果 <code>mouseover</code> 被触发了，则必须有 <code>mouseout</code> <br> 在鼠标快速移动的情况下，中间元素可能会被忽略，但是我们可以肯定一件事：如果鼠标指针进入了一个元素（生成了 <code>mouseover</code> 事件），那么一旦它离开，我们就会得到 <code>mouseout</code></p></blockquote><blockquote><p>当移动到一个子元素时会触发 <code>mouseout</code></p></blockquote><h3 id="_2-3-mouseenter-和-mouseleave" tabindex="-1">2.3 mouseenter 和 mouseleave <a class="header-anchor" href="#_2-3-mouseenter-和-mouseleave" aria-label="Permalink to &quot;2.3 mouseenter 和 mouseleave&quot;">​</a></h3><p>事件 mouseenter/mouseleave 类似于 mouseover/mouseout。它们在鼠标指针进入/离开元素时触发</p><p><strong>但是有两个重要的区别：</strong></p><ul><li>元素内部与后代之间的转换不会产生影响</li><li>事件 mouseenter/mouseleave 不会冒泡</li></ul><h2 id="_3-鼠标拖拽" tabindex="-1">3 鼠标拖拽 <a class="header-anchor" href="#_3-鼠标拖拽" aria-label="Permalink to &quot;3 鼠标拖拽&quot;">​</a></h2><p>基础的拖放算法如下所示：</p><ol><li>在 <code>mousedown</code> 上 —— 根据需要准备要移动的元素</li><li>然后在 mousemove 上，通过更改 <code>position:absolute</code> 情况下的 <code>left/top</code> 来移动它</li><li>在 <code>mouseup</code> 上 —— 执行与完成的拖放相关的所有行为</li></ol><h2 id="_4-指针事件" tabindex="-1">4 指针事件 <a class="header-anchor" href="#_4-指针事件" aria-label="Permalink to &quot;4 指针事件&quot;">​</a></h2><p>指针事件（Pointer Events）是一种用于处理来自各种输入设备（例如鼠标、触控笔和触摸屏等）的输入信息的现代化解决方案</p><h3 id="_4-1-历史" tabindex="-1">4.1 历史 <a class="header-anchor" href="#_4-1-历史" aria-label="Permalink to &quot;4.1 历史&quot;">​</a></h3><p>很早以前，只存在鼠标事件</p><p>后来，触屏设备开始普及，尤其是手机和平板电脑。为了使现有的脚本仍能正常工作，它们生成（现在仍生成）鼠标事件。例如，轻触屏幕就会生成 <code>mousedown</code> 事件。因此，触摸设备可以很好地与网页配合使用</p><p>但是，触摸设备比鼠标具有更多的功能。例如，我们可以同时触控多点（多点触控）。然而，鼠标事件并没有相关属性来处理这种多点触控</p><p>因此，引入了触摸事件，例如 <code>touchstart</code>、<code>touchend</code> 和 <code>touchmove</code>，它们具有特定于触摸的属性</p><p>不过这还是不够完美。因为很多其他输入设备（如触控笔）都有自己的特性。而且同时维护两份分别处理鼠标事件和触摸事件的代码，显得有些笨重</p><p>为了解决这些问题，人们引入了全新的规范「指针事件」。它为各种指针输入设备提供了一套统一的事件</p><p>目前，各大主流浏览器已经支持了 <code>Pointer Events Level 2</code> 标准，版本更新的 <code>Pointer Events Level 3</code> 已经发布，并且大多数情况下与 <code>Pointer Events Level 2</code> 兼容</p><blockquote><p>因此，除非你写的代码需要兼容旧版本的浏览器，例如 <code>IE 10</code> 或 <code>Safari 12</code> 或更低的版本，否则无需继续使用鼠标事件或触摸事件 —— <strong>我们可以使用指针事件</strong></p></blockquote><h3 id="_4-2-指针事件类型" tabindex="-1">4.2 指针事件类型 <a class="header-anchor" href="#_4-2-指针事件类型" aria-label="Permalink to &quot;4.2 指针事件类型&quot;">​</a></h3><p>指针事件的命名方式和鼠标事件类似：</p><table tabindex="0"><thead><tr><th>指针事件</th><th>类似的鼠标事件</th></tr></thead><tbody><tr><td>pointerdown</td><td>mousedown</td></tr><tr><td>pointerup</td><td>mouseup</td></tr><tr><td>pointermove</td><td>mousemove</td></tr><tr><td>pointerover</td><td>mouseover</td></tr><tr><td>pointerout</td><td>mouseout</td></tr><tr><td>pointerenter</td><td>mouseenter</td></tr><tr><td>pointerleave</td><td>mouseleave</td></tr><tr><td>pointercancel</td><td>-</td></tr><tr><td>gotpointercapture</td><td>-</td></tr><tr><td>lostpointercapture</td><td>-</td></tr></tbody></table><h3 id="_4-3-指针事件属性" tabindex="-1">4.3 指针事件属性 <a class="header-anchor" href="#_4-3-指针事件属性" aria-label="Permalink to &quot;4.3 指针事件属性&quot;">​</a></h3><p><strong>指针事件具备和鼠标事件完全相同的属性，包括 <code>clientX/Y</code> 和 <code>target</code> 等，以及一些其他属性：</strong></p><ul><li><code>pointerId</code> —— 触发当前事件的指针唯一标识符。浏览器生成的。使我们能够处理多指针的情况，例如带有触控笔和多点触控功能的触摸屏</li><li><code>pointerType</code> —— 指针的设备类型。可以是：<code>mouse</code>、<code>pen</code> 或 <code>touch</code></li><li><code>isPrimary</code> —— 当指针为首要指针（多点触控时按下的第一根手指）时为 true</li></ul><p><strong>有些指针设备会测量接触面积和点按压力（例如一根手指压在触屏上），对于这种情况可以使用以下属性：</strong></p><ul><li><code>width</code> —— 指针（例如手指）接触设备的区域的宽度。对于不支持的设备（如鼠标），这个值总是 1</li><li><code>height</code> —— 指针（例如手指）接触设备的区域的长度。对于不支持的设备，这个值总是 1</li><li><code>pressure</code> —— 触摸压力，是一个介于 0 到 1 之间的浮点数。对于不支持压力检测的设备，这个值总是 0.5（按下时）或 0</li><li><code>tangentialPressure</code> —— 归一化后的切向压力（tangential pressure）</li><li><code>tiltX</code>, <code>tiltY</code>, <code>twist</code> —— 针对触摸笔的几个属性，用于描述笔和屏幕表面的相对位置</li></ul><h3 id="_4-4-多点触控" tabindex="-1">4.4 多点触控 <a class="header-anchor" href="#_4-4-多点触控" aria-label="Permalink to &quot;4.4 多点触控&quot;">​</a></h3><p>指针事件使我们能够通过 <code>pointerId</code> 和 <code>isPrimary</code> 属性的帮助，能够处理多点触控</p><p>第一个手指触摸：<code>pointerdown</code> 事件触发，<code>isPrimary = true</code>，并且被指派了一个 <code>pointerId</code></p><p>第二个和后续的更多个手指触摸（假设第一个手指仍在触摸）：<code>pointerdown</code> 事件触发，<code>isPrimary = false</code>，并且每一个触摸都被指派了不同的 <code>pointerId</code></p><h3 id="_4-5-pointercancel-事件" tabindex="-1">4.5 pointercancel 事件 <a class="header-anchor" href="#_4-5-pointercancel-事件" aria-label="Permalink to &quot;4.5 pointercancel 事件&quot;">​</a></h3><p><code>pointercancel</code> 事件将会在一个正处于活跃状态的指针交互由于某些原因被中断时触发。也就是在这个事件之后，该指针就不会继续触发更多事件了</p><p><strong>导致指针中断的可能原因如下：</strong></p><ul><li>指针设备硬件在物理层面上被禁用</li><li>设备方向旋转（例如给平板转了个方向）</li><li>浏览器打算自行处理这一交互，比如将其看作是一个专门的鼠标手势或缩放操作等 (需要禁用 drag 事件)</li></ul><h3 id="_4-6-指针捕获" tabindex="-1">4.6 指针捕获 <a class="header-anchor" href="#_4-6-指针捕获" aria-label="Permalink to &quot;4.6 指针捕获&quot;">​</a></h3><p>指针捕获（Pointer capturing）是针对指针事件的一个特性</p><p><strong>主要的方法是：</strong></p><p><code>elem.setPointerCapture(pointerId)</code> —— 将给定的 <code>pointerId</code> 绑定到 <code>elem</code></p><p>在调用之后，所有具有相同 <code>pointerId</code> 的指针事件都将 <code>elem</code> 作为目标（就像事件发生在 <code>elem</code> 上一样），无论这些 <code>elem</code> 在文档中的实际位置是什么</p><p>换句话说，<code>elem.setPointerCapture(pointerId)</code> 将所有具有给定 <code>pointerId</code> 的后续事件重新定位到 <code>elem</code></p><p><strong>绑定会在以下情况下被移除：</strong></p><ul><li>当 <code>pointerup</code> 或 <code>pointercancel</code> 事件出现时，绑定会被自动地移除</li><li>当 <code>elem</code> 被从文档中移除后，绑定会被自动地移除</li><li>当 <code>elem.releasePointerCapture(pointerId)</code> 被调用，绑定会被移除</li></ul><p><strong>指针捕获为我们带来了两个好处：</strong></p><ol><li>代码变得更加简洁，我们不再需要在整个 document 上添加/移除处理程序。绑定会被自动释放</li><li>如果文档中有其他指针事件处理程序，则在用户拖动滑动条时，它们不会因指针的移动被意外地触发</li></ol><p><strong>还有两个与指针捕获相关的事件：</strong></p><ul><li><code>gotpointercapture</code> 会在一个元素使用 <code>setPointerCapture</code> 来启用捕获后触发</li><li><code>lostpointercapture</code> 会在捕获被释放后触发：其触发可能是由于 <code>releasePointerCapture</code> 的显式调用，或是 <code>pointerup/pointercancel</code> 事件触发后的自动调用</li></ul><h2 id="_5-键盘事件" tabindex="-1">5 键盘事件 <a class="header-anchor" href="#_5-键盘事件" aria-label="Permalink to &quot;5 键盘事件&quot;">​</a></h2><h3 id="_5-1-keydown-和-keyup" tabindex="-1">5.1 keydown 和 keyup <a class="header-anchor" href="#_5-1-keydown-和-keyup" aria-label="Permalink to &quot;5.1 keydown 和 keyup&quot;">​</a></h3><p><strong>event.code 和 event.key</strong></p><ul><li>事件对象的 <code>key</code> 属性允许获取字符</li><li>而事件对象的 <code>code</code> 属性则允许获取 “物理按键代码”</li></ul><table tabindex="0"><thead><tr><th>Key</th><th>event.key</th><th>event.code</th></tr></thead><tbody><tr><td>Z</td><td>z（小写）</td><td>KeyZ</td></tr><tr><td>Shift+Z</td><td>Z（大写）</td><td>KeyZ</td></tr></tbody></table><blockquote><p>如果用户使用不同的语言，那么切换到另一种语言将产生完全不同的字符，而不是 &quot;Z&quot;</p></blockquote><blockquote><p>如果按键没有给出任何字符。例如，<code>Shift</code> 或 <code>F1</code> 或其他。对于这些按键，它们的 <code>event.key</code> 与 <code>event.code</code> 大致相同</p></blockquote><blockquote><p><code>event.code</code> 准确地标明了哪个键被按下了。例如，大多数键盘有两个 <code>Shift</code> 键，一个在左边，一个在右边。<code>event.code</code> 返回按下了哪个键，而 <code>event.key</code> 返回它是什么（一个 Shift）</p></blockquote><p><code>event.code</code> 可能由于意外的键盘布局而与错误的字符进行了匹配。不同键盘布局中的相同字母可能会映射到不同的物理键，从而导致了它们有不同的代码</p><h3 id="_5-2-自动重复" tabindex="-1">5.2 自动重复 <a class="header-anchor" href="#_5-2-自动重复" aria-label="Permalink to &quot;5.2 自动重复&quot;">​</a></h3><p>如果按下一个键足够长的时间，它就会开始自动重复：<code>keydown</code> 会被一次又一次地触发，然后当按键被释放时，我们最终会得到 <code>keyup</code>。因此，有很多 <code>keydown</code> 却只有一个 <code>keyup</code> 是很正常的</p><blockquote><p>对于由自动重复触发的事件，<code>event</code> 对象的 <code>event.repeat</code> 属性被设置为 <code>true</code></p></blockquote><h3 id="_5-2-默认行为" tabindex="-1">5.2 默认行为 <a class="header-anchor" href="#_5-2-默认行为" aria-label="Permalink to &quot;5.2 默认行为&quot;">​</a></h3><p><strong>默认行为例如：</strong></p><ul><li>出现在屏幕上的一个字符</li><li>一个字符被删除（Delete 键）</li><li>滚动页面（PageDown 键）</li><li>浏览器打开保存页面对话框（Ctrl+S）</li></ul><p>阻止对 <code>keydown</code> 的默认行为可以取消大多数的行为，但基于 OS 的特殊按键除外。例如，在 Windows 中，<code>Alt+F4</code> 会关闭当前浏览器窗口。并且无法通过在 JavaScript 中阻止默认行为来阻止它</p><blockquote><p>从事件处理程序返回 <code>false</code> 会阻止事件的默认行为</p></blockquote><h3 id="_5-3-遗存" tabindex="-1">5.3 遗存 <a class="header-anchor" href="#_5-3-遗存" aria-label="Permalink to &quot;5.3 遗存&quot;">​</a></h3><p>过去曾经有一个 <code>keypress</code> 事件，还有事件对象的 <code>keyCod</code>e、<code>charCode</code> 和 <code>which</code> 属性</p><p>大多数浏览器对它们都存在兼容性问题，以致使该规范的开发者不得不弃用它们并创建新的现代的事件（本文上面所讲的这些事件）。旧的代码仍然有效，因为浏览器还在支持它们，但现在完全没必要再使用它们</p><h2 id="_6-滚动事件" tabindex="-1">6 滚动事件 <a class="header-anchor" href="#_6-滚动事件" aria-label="Permalink to &quot;6 滚动事件&quot;">​</a></h2><p>scroll 事件在 window 和可滚动元素上都可以运行。</p><p><strong>阻止滚动：</strong></p><p>我们不能通过在 <code>onscroll</code> 监听器中使用 <code>event.preventDefault()</code> 来阻止滚动，因为它会在滚动发生 <code>之后</code> 才触发</p><p>但是我们可以在导致滚动的事件上，例如在 <code>pageUp</code> 和 <code>pageDown</code> 的 <code>keydown</code> 事件上，使用 <code>event.preventDefault()</code> 来阻止滚动</p><p>启动滚动的方式有很多，使用 CSS 的 <code>overflow</code> 属性更加可靠</p>`,113)])])}const m=o(c,[["render",l]]);export{h as __pageData,m as default};
